const STATE_VERSION=10;
const CHAT_VOTE_POINTS=10;
const pointConfig={like:400,sub:400,member:400,superPerDollar:40000};
let musicUrl='assets/cutscene-crush.mp3';
const state={points:{},goal:50,totalUSD:0,lastChatToken:null,liveChatId:null,videoId:null,channelId:null,lastLikes:null,lastSubs:null,supporters:[],votes:[],voiceEnabled:false,voiceMode:'female',voiceEvents:{chat:true,like:true,sub:true,support:true,member:true},lastSpokenChat:null,viewerCountries:{},viewerCount:0,round:1,startedAt:Date.now(),eventFeed:[],voteTotal:0,processedMessages:{}};

// AI Voice: queued speech so the voice never cuts off the previous sentence.
const voiceQueue=[];
let voiceSpeaking=false;
let voiceTimer=null;
function chooseVoice(){
  const voices=window.speechSynthesis.getVoices();
  const femaleNames=/female|zira|samantha|victoria|karen|moira|ava|sara|sarah|susan|hazel|fiona|veena|lekha|nora|hoda|laila|salma|amira|aria|jenny/i;
  return state.voiceMode==='female'
    ? (voices.find(v=>femaleNames.test(v.name)) || voices.find(v=>/^ar|^fr|^en/i.test(v.lang)) || voices[0])
    : (voices.find(v=>/^ar|^fr|^en/i.test(v.lang)) || voices[0]);
}
function speak(text){
  if(!state.voiceEnabled || !('speechSynthesis' in window) || !text) return;
  voiceQueue.push(String(text).slice(0,220));
  processVoiceQueue();
}
function processVoiceQueue(){
  if(!state.voiceEnabled || voiceSpeaking || !voiceQueue.length || !('speechSynthesis' in window)) return;
  const text=voiceQueue.shift();
  try{
    voiceSpeaking=true;
    const u=new SpeechSynthesisUtterance(text);
    u.rate=1.0; u.pitch=1.0; u.volume=1.0;
    const preferred=chooseVoice();
    if(preferred) u.voice=preferred;
    u.onend=()=>{voiceSpeaking=false;setTimeout(processVoiceQueue,120);};
    u.onerror=()=>{voiceSpeaking=false;setTimeout(processVoiceQueue,120);};
    window.speechSynthesis.speak(u);
  }catch(e){voiceSpeaking=false;}
}
if('speechSynthesis' in window){window.speechSynthesis.onvoiceschanged=()=>{};}
function speakEvent(type,text){
  if(state.voiceEvents[type]!==false) speak(text);
}
function startAutoVoice(){
  clearInterval(voiceTimer);
  voiceTimer=setInterval(()=>{
    if(!state.voiceEnabled) return;
    const entries=Object.entries(state.points).sort((a,b)=>b[1]-a[1]).filter(x=>x[1]>0).slice(0,3);
    if(!entries.length) return;
    const lead=entries[0];
    const total=Object.values(state.points).reduce((a,b)=>a+(Number(b)||0),0);
    speak(`Current update: ${lead[0]} is leading with ${lead[1].toLocaleString()} points. The total is ${total.toLocaleString()} points. Keep voting and supporting your country!`);
  },30000);
}
function toggleVoice(){
  state.voiceEnabled=!state.voiceEnabled;
  const b=$('voiceToggle');
  if(b){b.textContent=state.voiceEnabled?'🔊 AI Voice: ON':'🔇 AI Voice: OFF';b.classList.toggle('on',state.voiceEnabled);}
  if(state.voiceEnabled){
    speak('AI voice is now on. I will keep announcing the live updates.');
    startAutoVoice();
  } else {
    voiceQueue.length=0; clearInterval(voiceTimer);
    if('speechSynthesis' in window){window.speechSynthesis.cancel();voiceSpeaking=false;}
  }
}

const $=id=>document.getElementById(id);
COUNTRIES.forEach(([flag,name])=>{state.points[name]=0; const o=document.createElement('option');o.value=name;o.textContent=`${flag} ${name}`;$('countrySelect').appendChild(o)});
const saved=JSON.parse(localStorage.getItem('boostCountryState')||'null');
if(saved){Object.assign(state.points,saved.points||{});state.goal=saved.goal||50;state.totalUSD=saved.totalUSD||0;state.supporters=saved.supporters||[];state.votes=saved.votes||[];state.voteTotal=Number(saved.voteTotal)||state.votes.length;state.viewerCountries=saved.viewerCountries||{};state.processedMessages=saved.processedMessages||{};Object.assign(pointConfig,saved.pointConfig||{});$('goalInput').value=state.goal}
if(saved?.voice){
  state.voiceEnabled=!!saved.voice.enabled;
  state.voiceMode=saved.voice.mode||'female';
  state.voiceEvents=Object.assign(state.voiceEvents,saved.voice.events||{});
}
function saveVoice(){
  save();
}

// Safety migration: the old like multiplier could create accidental multi-million jumps.
if(!saved || saved.version!==STATE_VERSION){
  const suspicious=Object.values(state.points).some(v=>Number(v)>1000000);
  if(suspicious){COUNTRIES.forEach(x=>state.points[x[1]]=0);state.totalUSD=0;state.supporters=[];log('Old abnormal point total cleared for safety.');}
  save();
}
function save(){localStorage.setItem('boostCountryState',JSON.stringify({version:STATE_VERSION,points:state.points,goal:state.goal,totalUSD:state.totalUSD,supporters:state.supporters.slice(0,20),votes:state.votes.slice(0,30),viewerCountries:state.viewerCountries,processedMessages:state.processedMessages,voteTotal:state.voteTotal,pointConfig,voice:{enabled:state.voiceEnabled,mode:state.voiceMode,events:state.voiceEvents}}))}
function flagForName(name){return (COUNTRIES.find(x=>x[1]===name)||['🌍'])[0]}
function render(){
 $('goalCurrent').textContent='$'+state.totalUSD.toFixed(2);$('goalTarget').textContent=state.goal;
 const pct=Math.min(100,Math.max(0,(state.totalUSD/Math.max(1,state.goal))*100));
 const gf=$('goalFill'),gp=$('goalPercent'); if(gf) gf.style.width=pct+'%'; if(gp) gp.textContent=Math.round(pct)+'%';
 const sorted=COUNTRIES.map(([flag,name])=>({flag,name,pts:Number(state.points[name])||0})).sort((a,b)=>(b.pts-a.pts)||a.name.localeCompare(b.name));
 const top=sorted.slice(0,3);
 // Visual podium: #2 left, #1 center, #3 right.
 const podiumOrder=top.length===3 ? [top[1],top[0],top[2]] : top;
 const podiumRanks=top.length===3 ? [1,0,2] : podiumOrder.map((_,i)=>i);
 $('podium').innerHTML=podiumOrder.map((x,i)=>`<div class="pod" data-country="${escapeHtml(x.name)}"><div class="medal"><span class="medal-icon">${['🥇','🥈','🥉'][podiumRanks[i]]}</span><span class="flag">${x.flag}</span><small>${escapeHtml(x.name)}</small><span class="pts">${x.pts.toLocaleString()} pts</span></div></div>`).join('');
 $('countries').innerHTML=sorted.map((x,i)=>`<div class="country" data-country="${escapeHtml(x.name)}"><div class="rank">#${i+1}</div><div class="flagbox">${x.flag}</div><div class="country-name">${escapeHtml(x.name)}</div><div class="pts">${x.pts.toLocaleString()} pts</div></div>`).join('');
 $('supporterList').innerHTML=state.supporters.length?state.supporters.slice(0,8).map(s=>`<div class="supporter"><b>${escapeHtml(s.name)}</b><strong>${escapeHtml(s.amount)}</strong></div>`).join(''):`<div class="empty">👑<br/>Waiting for Super Chat supporters...</div>`;
}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function showToast(message){const e=$('eventToast');if(!e)return;e.textContent=message;e.classList.remove('show');void e.offsetWidth;e.classList.add('show')}
function log(s){const e=document.createElement('div');e.textContent=new Date().toLocaleTimeString()+ ' — '+s;$('eventLog').prepend(e)}
function detectFlag(text){
  for(const [flag,name] of COUNTRIES){ if(text.includes(flag)) return name; }
  return null;
}
